import 'package:blockchain_utils/blockchain_utils.dart';
import 'package:on_chain/aptos/src/account/authenticator/authenticator.dart';
import 'package:on_chain/aptos/src/account/keyless/ephemeral.dart';

import 'package:on_chain/serialization/bcs/serialization/serialization.dart';

/// Groth16 BN254 proof points for Aptos keyless (AIP-61).
///
/// Wire form (matches `@aptos-labs/ts-sdk` `Groth16Zkp`): fixed raw bytes,
/// `a: [u8; 32]`, `b: [u8; 64]`, `c: [u8; 32]` — no length prefixes.
/// Proof bytes are opaque here: generated by the prover service, verified
/// on chain. No Dart-side pairing code exists by design.
class AptosGroth16Zkp extends BcsSerialization with Equality {
  final BuBytes a;
  final BuBytes b;
  final BuBytes c;

  AptosGroth16Zkp._({required this.a, required this.b, required this.c});

  factory AptosGroth16Zkp({
    required List<int> a,
    required List<int> b,
    required List<int> c,
  }) {
    void check(List<int> v, int n, String name) {
      if (v.length != n) {
        throw BuError(
          DefaultErrorType.invalidLength,
          'Invalid keyless proof point length.',
          details: {
            'field': name,
            'expected': n.toString(),
            'length': v.length.toString(),
          },
        );
      }
    }

    check(a, 32, 'a');
    check(b, 64, 'b');
    check(c, 32, 'c');
    return AptosGroth16Zkp._(
      a: a.asImmutableBytes,
      b: b.asImmutableBytes,
      c: c.asImmutableBytes,
    );
  }

  factory AptosGroth16Zkp.deserialize(List<int> bytes) {
    final decode = BcsSerialization.deserialize(bytes: bytes, layout: layout());
    return AptosGroth16Zkp.fromStruct(decode);
  }
  factory AptosGroth16Zkp.fromStruct(Map<String, dynamic> json) {
    return AptosGroth16Zkp(
      a: json.valueAsBytes('a'),
      b: json.valueAsBytes('b'),
      c: json.valueAsBytes('c'),
    );
  }

  static Layout<Map<String, dynamic>> layout({String? property}) {
    return LayoutConst.struct([
      LayoutConst.fixedBlobN(32, property: 'a'),
      LayoutConst.fixedBlobN(64, property: 'b'),
      LayoutConst.fixedBlobN(32, property: 'c'),
    ], property: property);
  }

  @override
  Layout<Map<String, dynamic>> createLayout({String? property}) {
    return layout(property: property);
  }

  @override
  Map<String, dynamic> toLayoutStruct() {
    return {'a': a, 'b': b, 'c': c};
  }

  @override
  List<dynamic> get variables => [a, b, c];
}

/// ZK proof container: `uleb128(variant) ++ proof` (Groth16 = 0).
class AptosZkProof extends BcsVariantSerialization with Equality {
  /// Groth16 variant index (matches `ZkpVariant` on chain).
  static const int groth16Variant = 0;

  final AptosGroth16Zkp proof;

  const AptosZkProof(this.proof);

  factory AptosZkProof.deserialize(List<int> bytes) {
    final decode = BcsVariantSerialization.deserialize(
      bytes: bytes,
      layout: layout(),
    );
    return AptosZkProof.fromStruct(decode);
  }
  factory AptosZkProof.fromStruct(Map<String, dynamic> json) {
    final decode = BcsVariantSerialization.toVariantDecodeResult(json);
    if (decode.variantName != 'groth16') {
      throw BuError(
        DefaultErrorType.unsupported,
        'Unsupported ZK proof variant.',
        details: {'variant': decode.variantName},
      );
    }
    return AptosZkProof(AptosGroth16Zkp.fromStruct(decode.value));
  }

  static Layout<Map<String, dynamic>> layout({String? property}) {
    return LayoutConst.bcsLazyEnum([
      LazyVariantModel(
        layout: AptosGroth16Zkp.layout,
        property: 'groth16',
        index: groth16Variant,
      ),
    ], property: property);
  }

  @override
  Layout<Map<String, dynamic>> createVariantLayout({String? property}) {
    return layout(property: property);
  }

  @override
  Layout<Map<String, dynamic>> createLayout({String? property}) {
    return layout(property: property);
  }

  @override
  String get variantName => 'groth16';

  @override
  Map<String, dynamic> toLayoutStruct() {
    return proof.toLayoutStruct();
  }

  @override
  List<dynamic> get variables => [proof];
}

/// Zero-knowledge signature: proof + horizons + optional fields.
class AptosZeroKnowledgeSig extends BcsSerialization with Equality {
  final AptosZkProof proof;

  /// Max lifespan of the proof in seconds.
  final BigInt expHorizonSecs;

  /// Optional revealed JWT claim (asserts identity on chain).
  final String? extraField;

  /// Optional recovery-service `aud` override.
  final String? overrideAudVal;

  /// Optional training-wheels signature: 66-byte `EphemeralSignature` BCS
  /// (`0x00` Ed25519 variant ++ `0x40`-prefixed 64-byte signature), exactly as
  /// returned by the prover service (`training_wheels_signature`) and sent by
  /// `@aptos-labs/ts-sdk` (`EphemeralSignature` BCS, whose inner
  /// `Ed25519Signature` is length-prefixed).
  final BuBytes? trainingWheelsSignature;

  AptosZeroKnowledgeSig({
    required this.proof,
    required this.expHorizonSecs,
    this.extraField,
    this.overrideAudVal,
    this.trainingWheelsSignature,
  }) {
    if (trainingWheelsSignature != null &&
        trainingWheelsSignature!.length != 66) {
      throw BuError(
        DefaultErrorType.invalidLength,
        'Invalid training-wheels signature length.',
        details: {'length': trainingWheelsSignature!.length.toString()},
      );
    }
  }

  factory AptosZeroKnowledgeSig.deserialize(List<int> bytes) {
    final decode = BcsSerialization.deserialize(bytes: bytes, layout: layout());
    return AptosZeroKnowledgeSig.fromStruct(decode);
  }
  factory AptosZeroKnowledgeSig.fromStruct(Map<String, dynamic> json) {
    return AptosZeroKnowledgeSig(
      proof: AptosZkProof.fromStruct(
        json.valueEnsureAsMap<String, dynamic>('proof'),
      ),
      expHorizonSecs: json.valueAsBigInt('expHorizonSecs'),
      extraField: json.valueAsString('extraField'),
      overrideAudVal: json.valueAsString('overrideAudVal'),
      trainingWheelsSignature: json.valueAsBytes('trainingWheelsSignature'),
    );
  }

  static Layout<Map<String, dynamic>> layout({String? property}) {
    return LayoutConst.struct([
      AptosZkProof.layout(property: 'proof'),
      LayoutConst.u64(property: 'expHorizonSecs'),
      LayoutConst.optional(LayoutConst.bcsString(), property: 'extraField'),
      LayoutConst.optional(LayoutConst.bcsString(), property: 'overrideAudVal'),
      LayoutConst.optional(
        LayoutConst.fixedBlobN(66),
        property: 'trainingWheelsSignature',
      ),
    ], property: property);
  }

  @override
  Layout<Map<String, dynamic>> createLayout({String? property}) {
    return layout(property: property);
  }

  @override
  Map<String, dynamic> toLayoutStruct() {
    return {
      'proof': proof.toVariantLayoutStruct(),
      'expHorizonSecs': expHorizonSecs,
      'extraField': extraField,
      'overrideAudVal': overrideAudVal,
      'trainingWheelsSignature': trainingWheelsSignature,
    };
  }

  @override
  List<dynamic> get variables => [proof, expHorizonSecs];
}

/// Ephemeral certificate: currently ZK-proof only (variant 0).
class AptosEphemeralCertificate extends BcsVariantSerialization with Equality {
  /// ZK-proof certificate variant.
  static const int zkProofVariant = 0;

  final AptosZeroKnowledgeSig signature;

  const AptosEphemeralCertificate(this.signature);

  factory AptosEphemeralCertificate.deserialize(List<int> bytes) {
    final decode = BcsVariantSerialization.deserialize(
      bytes: bytes,
      layout: layout(),
    );
    return AptosEphemeralCertificate.fromStruct(decode);
  }
  factory AptosEphemeralCertificate.fromStruct(Map<String, dynamic> json) {
    final decode = BcsVariantSerialization.toVariantDecodeResult(json);
    if (decode.variantName != 'zkProof') {
      throw BuError(
        DefaultErrorType.unsupported,
        'Unsupported ephemeral certificate variant.',
        details: {'variant': decode.variantName},
      );
    }
    return AptosEphemeralCertificate(
      AptosZeroKnowledgeSig.fromStruct(decode.value),
    );
  }

  static Layout<Map<String, dynamic>> layout({String? property}) {
    return LayoutConst.bcsLazyEnum([
      LazyVariantModel(
        layout: AptosZeroKnowledgeSig.layout,
        property: 'zkProof',
        index: zkProofVariant,
      ),
    ], property: property);
  }

  @override
  Layout<Map<String, dynamic>> createVariantLayout({String? property}) {
    return layout(property: property);
  }

  @override
  Layout<Map<String, dynamic>> createLayout({String? property}) {
    return layout(property: property);
  }

  @override
  String get variantName => 'zkProof';

  @override
  Map<String, dynamic> toLayoutStruct() {
    return signature.toLayoutStruct();
  }

  @override
  List<dynamic> get variables => [signature];
}

/// Ephemeral public key: `uleb128(Ed25519=0) ++ 32-byte key`.
class AptosEphemeralPublicKey extends BcsVariantSerialization with Equality {
  static const int ed25519Variant = 0;

  final BuBytes keyBytes;

  AptosEphemeralPublicKey(List<int> keyBytes)
    : keyBytes = keyBytes.asImmutableBytes {
    if (keyBytes.length != 32) {
      throw BuError(
        DefaultErrorType.invalidLength,
        'Invalid ephemeral public key length.',
        details: {'length': keyBytes.length.toString()},
      );
    }
  }

  factory AptosEphemeralPublicKey.deserialize(List<int> bytes) {
    final decode = BcsVariantSerialization.deserialize(
      bytes: bytes,
      layout: layout(),
    );
    return AptosEphemeralPublicKey.fromStruct(decode);
  }
  factory AptosEphemeralPublicKey.fromStruct(Map<String, dynamic> json) {
    final decode = BcsVariantSerialization.toVariantDecodeResult(json);
    if (decode.variantName != 'ed25519') {
      throw BuError(
        DefaultErrorType.unsupported,
        'Unsupported ephemeral public key variant.',
        details: {'variant': decode.variantName},
      );
    }
    return AptosEphemeralPublicKey(List<int>.from(decode.value['key'] as List));
  }

  static Layout<Map<String, dynamic>> _ed25519Key({String? property}) {
    return LayoutConst.struct([
      LayoutConst.bcsBytes(property: 'key'),
    ], property: property);
  }

  static Layout<Map<String, dynamic>> layout({String? property}) {
    return LayoutConst.bcsLazyEnum([
      LazyVariantModel(
        layout: _ed25519Key,
        property: 'ed25519',
        index: ed25519Variant,
      ),
    ], property: property);
  }

  @override
  Map<String, dynamic> toLayoutStruct() {
    return {'key': keyBytes};
  }

  @override
  Layout<Map<String, dynamic>> createVariantLayout({String? property}) {
    return layout(property: property);
  }

  @override
  Layout<Map<String, dynamic>> createLayout({String? property}) {
    return layout(property: property);
  }

  @override
  String get variantName => 'ed25519';

  @override
  List<dynamic> get variables => [keyBytes];
}

