  @override
  Layout<Map<String, dynamic>> createVariantLayout({String? property}) {
    return layout(property: property);
  }

  @override
  Layout<Map<String, dynamic>> createLayout({String? property}) {
    return layout(property: property);
  }

  @override
  List<dynamic> get variables => [signature];
}

/// Full keyless signature: certificate + JWT header + expiry + ephemeral
/// keypair artifacts (matches `KeylessSignature` BCS).
class AptosKeylessSignature extends BcsSerialization with Equality {
  final AptosEphemeralCertificate ephemeralCertificate;

  /// Raw JWT header JSON (as it appears in the token).
  final String jwtHeader;

  /// Ephemeral key expiry, seconds since epoch.
  final BigInt expiryDateSecs;
  final AptosEphemeralPublicKey ephemeralPublicKey;
  final AptosEphemeralSignature ephemeralSignature;

  const AptosKeylessSignature({
    required this.ephemeralCertificate,
    required this.jwtHeader,
    required this.expiryDateSecs,
    required this.ephemeralPublicKey,
    required this.ephemeralSignature,
  });

  factory AptosKeylessSignature.deserialize(List<int> bytes) {
    final decode = BcsSerialization.deserialize(bytes: bytes, layout: layout());
    return AptosKeylessSignature.fromStruct(decode);
  }
  factory AptosKeylessSignature.fromStruct(Map<String, dynamic> json) {
    return AptosKeylessSignature(
      ephemeralCertificate: AptosEphemeralCertificate.fromStruct(
        json.valueEnsureAsMap<String, dynamic>('ephemeralCertificate'),
      ),
      jwtHeader: json.valueAs('jwtHeader'),
      expiryDateSecs: json.valueAsBigInt('expiryDateSecs'),
      ephemeralPublicKey: AptosEphemeralPublicKey.fromStruct(
        json.valueEnsureAsMap<String, dynamic>('ephemeralPublicKey'),
      ),
      ephemeralSignature: AptosEphemeralSignature.fromStruct(
        json.valueEnsureAsMap<String, dynamic>('ephemeralSignature'),
      ),
    );
  }

  static Layout<Map<String, dynamic>> layout({String? property}) {
    return LayoutConst.struct([
      AptosEphemeralCertificate.layout(property: 'ephemeralCertificate'),
      LayoutConst.bcsString(property: 'jwtHeader'),
      LayoutConst.u64(property: 'expiryDateSecs'),
      AptosEphemeralPublicKey.layout(property: 'ephemeralPublicKey'),
      AptosEphemeralSignature.layout(property: 'ephemeralSignature'),
    ], property: property);
  }

  @override
  Layout<Map<String, dynamic>> createLayout({String? property}) {
    return layout(property: property);
  }

  @override
  Map<String, dynamic> toLayoutStruct() {
    return {
      'ephemeralCertificate': ephemeralCertificate.toVariantLayoutStruct(),
      'jwtHeader': jwtHeader,
      'expiryDateSecs': expiryDateSecs,
      'ephemeralPublicKey': ephemeralPublicKey.toVariantLayoutStruct(),
      'ephemeralSignature': ephemeralSignature.toVariantLayoutStruct(),
    };
  }

  /// Signs [digest] with [ephemeral] and wraps everything.
  factory AptosKeylessSignature.sign({
    required AptosEphemeralKeyPair ephemeral,
    required AptosZeroKnowledgeSig zkSig,
    required String jwtHeader,
    required List<int> digest,
  }) {
    return AptosKeylessSignature(
      ephemeralCertificate: AptosEphemeralCertificate(zkSig),
      jwtHeader: jwtHeader,
      expiryDateSecs: BigintUtils.parse(ephemeral.expiryDateSecs),
      ephemeralPublicKey: AptosEphemeralPublicKey(
        List<int>.from(ephemeral.privateKey.publicKey.toBytes()),
      ),
      ephemeralSignature: AptosEphemeralSignature(
        List<int>.from(ephemeral.sign(digest).toBytes()),
      ),
    );
  }

  @override
  List<dynamic> get variables => [ephemeralCertificate, jwtHeader];
}

/// `AnySignature` keyless variant (index 3, already in the enum).
class AptosKeylessAnySignature extends AptosAnySignature {
  final AptosKeylessSignature signature;

  const AptosKeylessAnySignature(this.signature)
    : super(type: AptosAnySignatures.keyless);

  factory AptosKeylessAnySignature.deserialize(List<int> bytes) {
    final decode = BcsSerialization.deserialize(bytes: bytes, layout: layout());
    return AptosKeylessAnySignature.fromStruct(decode);
  }
  factory AptosKeylessAnySignature.fromStruct(Map<String, dynamic> json) {
    return AptosKeylessAnySignature(
      AptosKeylessSignature.fromStruct(
        json.valueEnsureAsMap<String, dynamic>('signature'),
      ),
    );
  }

  static Layout<Map<String, dynamic>> layout({String? property}) {
    return LayoutConst.struct([
      AptosKeylessSignature.layout(property: 'signature'),
    ], property: property);
  }

  @override
  Layout<Map<String, dynamic>> createLayout({String? property}) {
    return layout(property: property);
  }

  @override
  Map<String, dynamic> toLayoutStruct() {
    return {'signature': signature.toLayoutStruct()};
  }

  @override
  BuBytes signatureBytes() {
    return signature.toBcs();
  }
}
